<?php
require_once 'config.php';require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT g.* FROM app_groups g JOIN group_members gm ON gm.group_id=g.id WHERE g.id=? AND gm.user_id=?');$s->execute([$id,$_SESSION['user_id']]);$g=$s->fetch();if(!$g){http_response_code(404);exit('Group not found or you are not a member.');}
$s=db()->prepare('SELECT u.name,u.roll_no,u.room_no,u.mobile,gm.threshold_value,gm.joined_at FROM group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=? ORDER BY gm.joined_at');$s->execute([$id]);$members=$s->fetchAll();$s=db()->prepare('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id WHERE o.group_id=? ORDER BY o.created_at');$s->execute([$id]);$orders=$s->fetchAll();$s=db()->prepare("SELECT COALESCE(SUM(price),0) FROM orders WHERE group_id=? AND status='Active'");$s->execute([$id]);$total=(float)$s->fetchColumn();$pageTitle='Group-'.$id;require 'header.php';?>
<div class="card"><h1>Group-<?=$id?></h1><p><b><?=e($g['hostel_name'])?> · <?=e($g['app_name'])?></b></p><p>Status: <b><?=e($g['status'])?></b> · Minimum threshold: ₹<?=e(number_format((float)$g['target_threshold'],2))?> · Combined purchase amount: ₹<?=e(number_format($total,2))?> · Members: <?=count($members)?></p><?php if($g['status']==='Completed'):?><div class="notice">Group complete! Members ki contact details ab available hain.</div><?php elseif($g['status']==='Open'):?><p>Threshold poora hone par sabhi members ko notification milegi.</p><?php endif;?><h2>Group members</h2><div class="tablewrap"><table><tr><th>Name</th><th>Roll No.</th><th>Room</th><?php if($g['status']==='Completed'):?><th>Mobile</th><?php endif;?><th>Threshold</th></tr><?php foreach($members as $m):?><tr><td><?=e($m['name'])?></td><td><?=e($m['roll_no'])?></td><td><?=e($m['room_no'])?></td><?php if($g['status']==='Completed'):?><td><a href="tel:<?=e($m['mobile'])?>"><?=e($m['mobile'])?></a></td><?php endif;?><td>₹<?=e(number_format((float)$m['threshold_value'],2))?></td></tr><?php endforeach;?></table></div><?php if($g['status']!=='Completed'):?><p>Mobile contact details group complete hone ke baad hi dikhengi.</p><?php endif;?><h2>Purchase details</h2><div class="tablewrap"><table><tr><th>Student</th><th>Purchase amount</th><th>Note</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['name'])?></td><td>₹<?=e(number_format((float)$o['price'],2))?></td><td><?=e($o['note'])?></td></tr><?php endforeach;?></table></div></div><?php require 'footer.php';?>\